import {rangePaths} from './edges.js';
import {garmentParts,componentParts} from './garment-effects.js';
import {uid,I,clone,worldPath,evaluatedPath,samples,uniform,offsetPoints,polyD,makePath,parsePath,point,pathD} from './core.js';
import {contours,offsetClosed,clipLines} from './geometry.js';
export const effectTypes=['stitch','parallel','zipper','cord','piping','binding','elastic','trim','buttons','eyelets','raw'];
export const effectNames={stitch:'Costura',parallel:'Paralela',zipper:'Cierre',cord:'Cordón',piping:'Vivo',binding:'Bies',elastic:'Elástico',trim:'Cinta',buttons:'Botones',eyelets:'Ojales',raw:'Borde crudo',rib:'Rib',bend:'Curvar',fabricFall:'Caída / Stack',pleat:'Pliegues',quilt:'Quilt',distress:'Desgaste'};
export function pathLength(pts){let n=0;for(let i=1;i<pts.length;i++)n+=Math.hypot(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);return n;}
export function frame(pts,i){const a=pts[Math.max(0,i-1)],b=pts[Math.min(pts.length-1,i+1)],l=Math.hypot(b.x-a.x,b.y-a.y)||1;return {tx:(b.x-a.x)/l,ty:(b.y-a.y)/l,nx:-(b.y-a.y)/l,ny:(b.x-a.x)/l};}
const part=(d,stroke,width,fill='none',extra={})=>({d,stroke,width,fill,...extra});
const at=(p,f,n,t=0)=>({x:p.x+f.nx*n+f.tx*t,y:p.y+f.ny*n+f.ty*t});
const circle=(p,r)=>`M ${p.x-r} ${p.y} C ${p.x-r} ${p.y-r*1.333} ${p.x+r} ${p.y-r*1.333} ${p.x+r} ${p.y} C ${p.x+r} ${p.y+r*1.333} ${p.x-r} ${p.y+r*1.333} ${p.x-r} ${p.y} Z`;
function rectangle(p,f,w,h){return polyD([at(p,f,-w/2,-h/2),at(p,f,w/2,-h/2),at(p,f,w/2,h/2),at(p,f,-w/2,h/2)])+' Z';}
const cache=new Map();
export function effectParts(effect,source){const key=JSON.stringify([effect,source.nodes,source.matrix,source.modifiers,source.closed,source.subpaths,source.component]);if(cache.has(key))return cache.get(key);const result=effect.edgeIds?.length?rangePaths(source,effect.edgeIds).flatMap(p=>generate({...effect,edgeIds:undefined},p)):generate(effect,source);if(cache.size>180)cache.clear();const owned=result.map(p=>({...p,ownerId:effect.id,ownerModifier:effect.ownerModifier}));cache.set(key,owned);return owned;}
function generate(o,s){let pts=uniform(samples(worldPath(s),48),1.5);if(pts.length<2)return [];const ring=samples(worldPath(s),48),area=ring.reduce((v,a,i)=>{const b=ring[(i+1)%ring.length];return v+a.x*b.y-b.x*a.y;},0),normalSign=s.interiorSign??(s.closed?(Math.sign(area)||1):Math.sign(s.matrix[0]*s.matrix[3]-s.matrix[1]*s.matrix[2])||1);const color=o.stroke||'#444b49',width=o.width??.85,result=[];
if(o.type==='stitch'&&o.position==='centered'&&!o.edgeIds?.length&&o.rows!==2&&o.stitchType!=='zigzag')return [part(pathD(worldPath(s)),color,width,'none',{dash:`${o.length??3} ${o.spacing??3}`})];
if(o.type==='stitch'||o.type==='parallel'){const side=o.position==='centered'?0:o.position==='outside'?-1:1;const rows=o.type==='stitch'?(o.rows||1):1;for(let row=0;row<rows;row++){const distance=side*((o.offset??5)+row*(o.rowGap??4)),lines=s.closed?(Math.abs(distance)>.001?offsetClosed(contours(s),-distance):contours(s)):[offsetPoints(pts,distance*normalSign)];for(const off of lines){if(o.stitchType==='zigzag'){const zig=uniform(off,Math.max(1,o.length||3));const ps=zig.map((p,i)=>at(p,frame(zig,i),normalSign*(i%2?2:-2)));result.push(part(polyD(ps)+(s.closed?' Z':''),color,width));}else if(o.type==='stitch')result.push(part(polyD(off)+(s.closed?' Z':''),color,width,'none',{dash:`${o.length??3} ${o.spacing??3}`}));else result.push(part(polyD(off)+(s.closed?' Z':''),color,width));}}return result;}
if(['piping','binding','trim','elastic','raw'].includes(o.type)){const side=o.position==='centered'?0:o.position==='outside'?-1:1;pts=offsetPoints(pts,side*(o.offset??0)*normalSign);}if(o.type==='zipper'){const w=o.zipWidth??7,tape=o.tapeWidth??3,spacing=Math.max(.8,o.teethSpacing??o.teeth??3),size=Math.max(.1,o.teeth??3)*(o.zipType==='invisible'?.35:.65),tw=o.teethWidth??w/2,L=pathLength(pts),slider=Math.max(0,Math.min(1,o.slider??.12)),open=Math.max(0,Math.min(1,(o.openAmount??0)/100)),gapAt=f=>f<slider&&slider>0?open*48*Math.pow(1-f/slider,1.25):0;let dist=0;const left=[],right=[];for(let i=0;i<pts.length;i++){if(i)dist+=Math.hypot(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);const f=frame(pts,i),gap=gapAt(dist/(L||1));left.push(at(pts[i],f,-w/2-gap));right.push(at(pts[i],f,w/2+gap));}result.push(part(polyD(left),o.tapeColor||color,tape,'none',{opacity:.4}),part(polyD(right),o.tapeColor||color,tape,'none',{opacity:.4}));const tooth=uniform(pts,spacing);let walked=0;for(let i=0;i<tooth.length;i++){if(i)walked+=Math.hypot(tooth[i].x-tooth[i-1].x,tooth[i].y-tooth[i-1].y);if(i===tooth.length-1&&walked%spacing<spacing*.6)continue;const f=frame(tooth,i),sign=i%2?1:-1,gap=gapAt(walked/(L||1)),p=at(tooth[i],f,sign*(gap+tw/2));result.push(part(rectangle(p,f,tw,size),'none',0,color,{role:'tooth'}));}const index=Math.min(pts.length-1,Math.round(slider*(pts.length-1))),p=pts[index],f=frame(pts,index);result.push(part(rectangle(p,f,w+3,9),color,.8,'#aeb7b1',{role:'slider'}),part(rectangle(at(p,f,0,8),f,4,14),color,.8,'#d9ddda'));for(const index of [0,pts.length-1]){const f=frame(pts,index);for(const sign of [-1,1])result.push(part(rectangle(at(pts[index],f,sign*(w/2+gapAt(index?1:0))),f,tape+1,3),color,.5,color));}return result;}
if(o.type==='cord'||['piping','binding','trim'].includes(o.type)){const w=o.type==='cord'?(o.cordWidth??5):(o.effectWidth??5);result.push(part(polyD(pts),color,w));if(o.type==='binding'||o.type==='trim'||o.cordStyle==='flat')for(const side of [-1,1])result.push(part(polyD(offsetPoints(pts,side*w*.28)),'#ffffff',.55,'none',{opacity:.35}));if(o.type==='cord'&&['braided','elastic'].includes(o.cordStyle)){const weave=uniform(pts,Math.max(2,w*.6));for(const sign of [-1,1])result.push(part(polyD(weave.map((p,i)=>at(p,frame(weave,i),sign*Math.sin(i*1.5)*w*.3))),'#ffffff',.65,'none',{opacity:.65}));}if(o.type==='cord'){const last=pts.at(-1),f=frame(pts,pts.length-1);if(o.endType!=='none')result.push(part(o.endType==='knot'?circle(last,w*.65):rectangle(at(last,f,0,-2),f,w+1,10),color,.7,o.endType==='knot'?color:'#b9c0b8'));}return result;}
if(o.type==='elastic'){const w=o.effectWidth??8;result.push(part(polyD(pts),color,w,'none',{opacity:.12}));const ps=uniform(pts,Math.max(2,o.spacing??5));result.push(part(polyD(ps.map((p,i)=>at(p,frame(ps,i),i%2?w/2:-w/2))),color,width));return result;}
if(o.type==='buttons'||o.type==='eyelets'){const count=Math.max(1,Math.min(200,Math.round(o.count??5))),r=Math.max(.1,o.itemSize??5),ps=uniform(pts,Lstep(pts,count));for(let i=0;i<count;i++){const index=count===1?Math.floor(pts.length/2):Math.round(i*(pts.length-1)/(count-1)),p=pts[index];result.push(part(circle(p,r),color,1,o.type==='buttons'?'#e5e8e1':'none'));result.push(part(circle(p,o.type==='eyelets'?r*.6:r*.15),color,.7,o.type==='eyelets'?'none':color));}return result;}
if(o.type==='raw'){const ps=uniform(pts,Math.max(1,o.spacing??3)),seed=o.seed??1;const rand=i=>{const x=Math.sin(i*127.1+seed*311.7)*43758.5453;return x-Math.floor(x);};const jag=ps.map((p,i)=>at(p,frame(ps,i),normalSign*((rand(i)-.5)*(o.randomness??.5)+Math.sin(i*2.3))*(o.intensity??2)));result.push(part(polyD(jag),color,width));for(let i=1;i<ps.length-1;i++)result.push(part(polyD([jag[i],at(ps[i],frame(ps,i),normalSign*(o.position==='outside'?-1:1)*(o.length??4)*(rand(i+99)*.5+.5))]),color,width*.65));return result;}return result;}
const Lstep=(pts,c)=>Math.max(.1,pathLength(pts)/Math.max(1,c-1));
export function ribParts(source,mod){const key=JSON.stringify(['rib',source.nodes,source.matrix,source.modifiers,source.subpaths,source.component,mod]);if(cache.has(key))return cache.get(key);const shape=worldPath(source),world=contours(source);if(!world.length)return [];const margin=Math.max(0,mod.inset??2),inside=margin?offsetClosed(world,-margin):world;if(!inside.length)return [];const angle=(mod.angle||0)*Math.PI/180,follow=['follow','edge'].includes(mod.direction||'follow');let ux=1,uy=0;if(follow){const m=source.matrix,den=Math.hypot(m[0],m[1])||1;ux=m[0]/den;uy=m[1]/den;}if(mod.direction==='horizontal'){ux=0;uy=1;}if(angle){const x=ux*Math.cos(angle)-uy*Math.sin(angle);uy=ux*Math.sin(angle)+uy*Math.cos(angle);ux=x;}const vx=-uy,vy=ux;const projected=inside.map(poly=>poly.map(p=>({x:p.x*ux+p.y*uy,y:p.x*vx+p.y*vy}))),pts=projected.flat(),min=Math.min(...pts.map(p=>p.x)),max=Math.max(...pts.map(p=>p.x)),gap=Math.max(.6,(mod.spacing??5)/Math.max(.1,mod.density??1));const intersections=u=>{const values=[];for(const ring of projected)for(let i=0;i<ring.length;i++){const a=ring[i],b=ring[(i+1)%ring.length];if((a.x<=u&&b.x>u)||(b.x<=u&&a.x>u))values.push(a.y+(b.y-a.y)*(u-a.x)/(b.x-a.x));}return values.sort((a,b)=>a-b);};const center=u=>{const v=intersections(Math.max(min+.01,Math.min(max-.01,u)));return v.length?(mod.direction==='edge'?v[0]:(v[0]+v.at(-1))/2):0;};const lines=[];for(let u=min+gap/2,n=0;u<max&&n<1500;u+=gap,n++){const vs=intersections(u);for(let k=0;k+1<vs.length;k+=2){const top=vs[k],bottom=vs[k+1],mid=(top+bottom)/2,slope=follow?(center(u+1)-center(u-1))/2:0;const line=[];for(let j=0;j<=8;j++){const v=top+(bottom-top)*j/8,adjustedU=u-slope*(v-mid);line.push({x:adjustedU*ux+v*vx,y:adjustedU*uy+v*vy});}lines.push(line);}}const clipped=clipLines(lines,inside);const parts=clipped.map(line=>part(polyD(line),mod.stroke||'#9ca79d',mod.thickness??.6));if(cache.size>180)cache.clear();cache.set(key,parts);return parts;}
export function modifierParts(source){const parts=componentParts(source,effectParts).map(p=>({...p,ownerId:source.id}));for(const m of source.modifiers||[]){if(m.enabled===false||m.type==='bend')continue;const start=parts.length;if(m.type==='rib'){if(m.edgeIds?.length)parts.push(...rangePaths(source,m.edgeIds).flatMap(p=>edgeRibParts(p,m)));else parts.push(...ribParts(source,m));}else if(['fabricFall','quilt','pleat','distress'].includes(m.type))parts.push(...garmentParts(source,m));else if(effectTypes.includes(m.type))parts.push(...effectParts({...m,ownerModifier:m.id,width:m.thickness??m.width??.85},source));for(let i=start;i<parts.length;i++){parts[i]={...parts[i],ownerId:source.id,ownerModifier:m.id};}}return parts;}
export function modifier(type,extra={}){return {id:uid(),type,enabled:true,...(type==='fabricFall'?{length:70,intensity:5,irregularity:.3,foldCount:3,seed:1,region:'hem',thickness:.8,stroke:'#252a29'}:type==='quilt'?{pattern:'horizontal',spacing:24,angle:0,inset:3,thickness:.8}:type==='pleat'?{pleatType:'knife',pleatWidth:18,depth:4,direction:'vertical',count:5,inset:3,thickness:.8}:type==='distress'?{count:8,length:12,seed:1,inset:3,thickness:.6}:type==='rib'?{position:'inside',direction:'follow',spacing:5,thickness:.6,inset:2,density:1,stroke:'#9ca79d'}:type==='bend'?{amount:0}:{rows:1,offset:5,spacing:3,length:3,thickness:.85,stroke:'#444b49',position:'inside',rowGap:4}),...extra};}
export function freezeParts(parts,name){return parts.map((p,i)=>makePath(name+' '+(i+1),p.d,p.fill,{stroke:p.stroke,width:p.width,opacity:p.opacity??1,dash:p.dash}));}
export function reversePath(o){const old=o.nodes.map(n=>({edgeId:n.edgeId,edgeParents:n.edgeParents})),len=o.nodes.length;o.nodes.reverse();for(let j=0;j<len;j++){const n=o.nodes[j],i=n.in;n.in=n.out;n.out=i;const previous=old[(len-2-j+len)%len];if(o.closed||j<len-1){n.edgeId=previous.edgeId;n.edgeParents=previous.edgeParents;}}return o;}
export function resizePathLength(source,target){const w=worldPath(source),len=pathLength(samples(w,60));if(len<.001||target<0)return;const origin={...source.nodes[0]},factor=target/len;for(const n of source.nodes)for(const p of [n,n.in,n.out].filter(Boolean)){p.x=origin.x+(p.x-origin.x)*factor;p.y=origin.y+(p.y-origin.y)*factor;}}

function edgeRibParts(source,m){const sign=(source.interiorSign??1)*(m.position==='outside'?-1:m.position==='centered'?0:1);const pts=uniform(samples(worldPath(source),36),Math.max(.8,m.spacing??5)),result=[];for(let i=0;i<pts.length;i++){const f=frame(pts,i),depth=m.effectWidth??12;result.push(part(polyD([at(pts[i],f,sign*(m.inset??0)),at(pts[i],f,sign*depth)]),m.stroke||'#667d6b',m.thickness??.6));}return result;}
